use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Clone,Copy,Debug,PartialEq,Serialize,Deserialize)]pub struct Root{pub value:f64,pub residual:f64,pub multiplicity_hint:u8}
pub fn real_cubic_roots(p:f64,q:f64,tol:f64)->Result<Vec<Root>,NumericalError>{if !p.is_finite()||!q.is_finite()||tol<=0.0{return Err(NumericalError::Input)}let disc=(q/2.0).powi(2)+(p/3.0).powi(3);let mut roots=if disc>tol{let s=disc.sqrt();vec![(-q/2.0+s).cbrt()+(-q/2.0-s).cbrt()]}else if disc.abs()<=tol{let u=(-q/2.0).cbrt();vec![2.0*u,-u]}else{let radius=2.0*(-p/3.0).sqrt();let arg=((3.0*q/(2.0*p))*(-3.0/p).sqrt()).clamp(-1.0,1.0);let theta=arg.acos()/3.0;vec![radius*theta.cos(),radius*(theta-2.0*std::f64::consts::PI/3.0).cos(),radius*(theta-4.0*std::f64::consts::PI/3.0).cos()]};roots.sort_by(f64::total_cmp);roots.dedup_by(|a,b|(*a-*b).abs()<=tol);Ok(roots.into_iter().map(|x|Root{value:x,residual:x.powi(3)+p*x+q,multiplicity_hint:if(3.0*x*x+p).abs()<=tol{2}else{1}}).collect())}
pub fn symmetric_eigenvalues_2x2(a:f64,b:f64,d:f64)->Result<[f64;2],NumericalError>{if[a,b,d].iter().any(|v|!v.is_finite()){return Err(NumericalError::Input)}let trace=a+d;let radius=((a-d).powi(2)+4.0*b*b).sqrt();Ok([(trace-radius)/2.0,(trace+radius)/2.0])}
pub fn invert_matrix(mut a:Vec<Vec<f64>>)->Result<Vec<Vec<f64>>,NumericalError>{let n=a.len();if n==0||a.iter().any(|r|r.len()!=n||r.iter().any(|v|!v.is_finite())){return Err(NumericalError::Input)}let mut inv=vec![vec![0.0;n];n];for(i,row)in inv.iter_mut().enumerate(){row[i]=1.0}for col in 0..n{let pivot=(col..n).max_by(|&i,&j|a[i][col].abs().total_cmp(&a[j][col].abs())).ok_or(NumericalError::Singular)?;if a[pivot][col].abs()<1e-14{return Err(NumericalError::Singular)}a.swap(col,pivot);inv.swap(col,pivot);let s=a[col][col];for j in 0..n{a[col][j]/=s;inv[col][j]/=s}for i in 0..n{if i==col{continue}let f=a[i][col];for j in 0..n{a[i][j]-=f*a[col][j];inv[i][j]-=f*inv[col][j]}}}Ok(inv)}
#[derive(Debug,Error)]pub enum NumericalError{#[error("invalid numerical input")]Input,#[error("singular matrix")]Singular}
